def permissions_vers_fonctionnalites(apps, schema_editor):
    """Cree les fonctionnalites du catalogue et convertit les anciennes
    listes de permissions (JSON) des groupes en liaisons."""
    from apps.utilisateurs.groupes import synchroniser_fonctionnalites, attribuer

    Fonctionnalite = apps.get_model("utilisateurs", "Fonctionnalite")
    Groupe = apps.get_model("utilisateurs", "Groupe")
    Liaison = apps.get_model("utilisateurs", "FonctionnaliteGroupe")
    synchroniser_fonctionnalites(Fonctionnalite)
    for groupe in Groupe.objects.all():
        if groupe.acces_total:
            ids = list(Fonctionnalite.objects.values_list("pk", flat=True))
        else:
            ids = list(Fonctionnalite.objects.filter(nom__in=groupe.permissions or []).values_list("pk", flat=True))
        attribuer(groupe, ids, Liaison)


